        Document document = Document.createShell("https://example.com");
        assertEquals("https://example.com", document.location());
    }

    @Test
    public void connection_connectionReturned() {
        Connection connection = Jsoup.connect("https://example.com");
        Document document = Document.createShell(connection.getUri().toString());
        assertEquals(connection, document.connection());
    }

    @Test
    public void head_elementReturned() {
        Document document = Document.createShell("https://example.com");
        Element head = document.head();
        assertNotNull(head);
    }

    @Test
    public void body_elementReturned() {
        Document document = Document.createShell("https://example.com");
        Element body = document.body();
        assertNotNull(body);
    }

    @Test
    public void forms_elementsReturned() {
        Document document = Document.createShell("https://example.com");
        List<FormElement> forms = document.forms();
        assertTrue(forms.size() > 0);
    }

    @Test
    public void expectForm_cssQueryReturned() {
        Document document = Document.createShell("https://example.com");
        FormElement form = document.expectForm("form");
        assertNotNull(form);
    }

    @Test
    public void title_titleReturned() {
        Document document = Document.createShell("https://example.com");
        String title = document.title();
        assertTrue(title.isEmpty());
    }

    @Test
    public void createElement_tagNameReturned() {
